/* 한줄평에서 고를 수 있는 아이콘 (write.js · detail.js 공통)
   · 화살표 · 닫기 · 더하기 · 인용부호는 UI용이라 뺐고,
     로고 · 새 카페 뱃지 · 컵 · 재방문용 하트(heart, heart-line) 같은 고정 색/상태 아이콘도 뺐어요. */
const NOTE_ICON_CHOICES = [
  'gift', 'party', 'think', 'heart-note', 'fire',
  'coffee', 'cake', 'book', 'pencil', 'camera', 'note',
  'sunny', 'cloud', 'rain', 'snow',
];
/* 한줄평 포스트잇 색 (CSS의 .postit--이름 과 짝) — 최대 5개라 서로 안 겹치게 5가지 */
const NOTE_COLORS = ['butter', 'sky', 'sage', 'rose', 'lilac'];

const DEFAULT_NOTE_ICONS = ['gift', 'party', 'think', 'heart-note'];   // 예전 기록(순서별 아이콘)용

/* 이름으로 SVG 문자열 만들기
   · 피그마 아이콘(viewBox · body가 있는 것): 선 굵기·색을 파일에 적힌 그대로 사용
   · 직접 그린 아이콘(글자로만 적은 것): 24×24 · 선 1.5px 기본값을 사용 */
function iconSvg(name) {
  const icon = ICONS[name];
  if (!icon) return '';
  if (icon.body) {
    return `<svg viewBox="${icon.viewBox}" fill="none" aria-hidden="true">${icon.body}</svg>`;
  }
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"
    stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon}</svg>`;
}

/* 화면 안의 <i data-icon="..."> 를 모두 실제 아이콘으로 바꾸기
   (화면을 새로 그릴 때마다 다시 불러 줍니다) */
function renderIcons(root = document) {
  root.querySelectorAll('[data-icon]').forEach((el) => {
    if (el.dataset.iconDone) return;
    el.innerHTML = iconSvg(el.dataset.icon);
    el.classList.add('icon');
    el.dataset.iconDone = '1';
  });
}
